    """Return True if s is a valid IPv4 address.
    Rules:
    - Four decimal numbers separated by '.'
    - Each number between 0 and 255 inclusive
    - No leading zeros unless the number is exactly "0"
    - Only digits allowed in each part
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # No leading zeros unless single zero
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if not (0 <= val <= 255):
            return False
    return True

