def solve(line: str):
    # If the line is empty, return a list with an empty string
    if line == "":
        return [""]
    fields = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == '"':
            # quoted field
            i += 1
            field_chars = []
            while i < n:
                if line[i] == '"':
                    # check if it's an escaped double quote
                    if i + 1 < n and line[i+1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        # end of quoted field
                        i += 1
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            field = ''.join(field_chars)
            # after quoted field, expect comma or end
            if i < n and line[i] == ',':
                i += 1  # skip delimiter
            fields.append(field)
        else:
            # unquoted field: read until comma
            start = i
            while i < n and line[i] != ',':
                i += 1
            field = line[start:i]
            # skip delimiter if present
            if i < n and line[i] == ',':
                i += 1
            fields.append(field)
