def solve(matrix):
    """Return the determinant of an integer square matrix using the Bareiss algorithm.
    An empty matrix (0x0) has determinant 1.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a deep copy to avoid mutating input
    A = [list(row) for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Pivot element
        if A[k][k] == 0:
            # Find a row to swap
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        prev = 1 if k == 0 else A[k - 1][k - 1]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev
        # Zero out the column below the pivot
        for i in range(k + 1, n):
            A[i][k] = 0
    return det_sign * A[n - 1][n - 1]

