def solve(meetings):
    # Edge case
    if not meetings:
        return 0
    # Sort by end time
    meetings = sorted(meetings, key=lambda x: x[1])
    count = 0
    end_time = -float('inf')
    for s, e in meetings:
        if s >= end_time:
            count += 1
            end_time = e
    return count
